"""Relocate redundant mesh columns without resampling the rest of a side.

Try at most four local changes. Replace one interior station of a very
short interval by the midpoint of the first sufficiently long, nonadjacent
interval. Endpoints, side counts and all other parameters stay exact. The caller
must check complete boundary preservation and final surface quality; this
heuristic alone does not authorize a changed curb or guarantee usable quads.
The default relocates the later endpoint; the opt-in earlier alternative can
preserve a real curb bend immediately after a cluster of near-coincident joins.
The opt-in centered alternative retains the close pair's midpoint and moves
the freed station elsewhere. It uses a 5%-of-cell short-interval threshold;
the caller must enforce the same complete outline bound and surface guards.
Continuous activation fades this operation at that same cutoff by blending
the ordered station tables. It does not certify other selection transitions.
The separate local-spacing experiment applies continuous neighbour pressure
to all short gaps without sorting or selecting pairs. It handles clusters with
a fixed iteration budget; boundary and surface qualification is still required.
The current anchored variant improves three recorded baselines, but one edited
surface fails independent boundary preservation and two other patches retain
poor fallback quads. It is private and not qualified for production adoption.
"""
import bpy
from . import curved_quad_patch_nodes as four

c=four.c


def build(*,earlier=False,centered=False,continuous=False,local_spacing=False):
    if local_spacing:
        if earlier or centered or continuous:raise ValueError('Local spacing has its own continuous pressure policy')
        return local_cluster_spacing(anchored=True)
    if centered and earlier:raise ValueError('Centered redistribution has its own endpoint policy')
    if continuous and not centered:raise ValueError('Continuous redistribution requires centered stations')
    name='Prochitecture Streets / Locally redistributed quad stations v1'
    if earlier:name+=' / Earlier endpoint'
    if centered:name+=' / Centered short interval v1'
    if continuous:name+=' / Continuous activation v1'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    original=four.stations();g=c.Graph(name)
    for socket in original.interface.items_tree:
        if socket.item_type=='SOCKET':
            g.socket(socket.name,socket.socket_type,socket.in_out,default=getattr(socket,'default_value',None))
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput')
    call=g.node('GeometryNodeGroup');call.node_tree=original
    for socket in original.interface.items_tree:
        if socket.item_type=='SOCKET' and socket.in_out=='INPUT':g.bind(inp.outputs[socket.name],call.inputs[socket.name])
    length=c._read(g,inp.outputs['Plan'],'st_cq_length',inp.outputs['Index'])
    cell=g.math('MAXIMUM',c.V(g,inp.outputs['Cell Size']),.02)
    ri=g.node('GeometryNodeRepeatInput','At most four local column relocations')
    ro=g.node('GeometryNodeRepeatOutput');ri.pair_with_output(ro)
    g.bind(call.outputs['Geometry'],ri.inputs['Geometry'])
    g.bind(c.choose(g,call.outputs['Valid'],4,0,'INT'),ri.inputs['Iterations'])
    table=ri.outputs['Geometry'];count=c._count(g,table)
    index=c.V(g,g.node('GeometryNodeInputIndex').outputs[0]);t=c.named(g,'st_cq_t')
    previous=c._read(g,table,'st_cq_t',g.math('MAXIMUM',index-1.,0.))
    following=c._read(g,table,'st_cq_t',g.math('MINIMUM',index+1.,count-1.))
    interior=g.math('GREATER_THAN',index,.5)*g.math('LESS_THAN',index,count-1.5)
    gap=following-t if earlier else t-previous
    short=interior*g.math('LESS_THAN',gap*length,(.05 if centered else .01)*cell)
    if centered:
        # Both endpoints of the close pair must be interior. Full incoming
        # profile endpoints are never candidates for relocation.
        short=short*g.math('GREATER_THAN',index,1.5)
    remove=c._stat(g,table,c.choose(g,short,index,four.MAX_ROWS),'Min')
    # Do not split either interval adjoining the removed station.
    nonadjacent=(1.-g.math('COMPARE',index,remove))*(1.-g.math('COMPARE',index,remove-1.))
    if centered:nonadjacent=nonadjacent*(1.-g.math('COMPARE',index,remove-2.))
    roomy=nonadjacent*g.math('GREATER_THAN',(following-t)*length,.5*cell)
    split=c._stat(g,table,c.choose(g,roomy,index,four.MAX_ROWS),'Min')
    active=g.math('LESS_THAN',remove,count)*g.math('LESS_THAN',split,count-1.)
    a=c._read(g,table,'st_cq_t',g.math('MINIMUM',split,count-1.))
    b=c._read(g,table,'st_cq_t',g.math('MINIMUM',split+1.,count-1.))
    updated=c.choose(g,active*g.math('COMPARE',index,remove),.5*(a+b),t)
    if centered:
        left=c._read(g,table,'st_cq_t',g.math('MAXIMUM',0.,g.math('MINIMUM',remove-1.,count-1.)))
        right=c._read(g,table,'st_cq_t',g.math('MINIMUM',remove,count-1.))
        updated=c.choose(g,active*g.math('COMPARE',index,remove-1.),.5*(left+right),updated)
    changed=c._store(g,table,'st_cq_t',updated)
    sort=g.node('GeometryNodeSortElements');sort.domain='POINT'
    g.bind(changed,sort.inputs['Geometry']);g.bind(c.named(g,'st_cq_t'),sort.inputs['Sort Weight'])
    redistributed=sort.outputs['Geometry']
    if continuous:
        # Interpolate ordered tables, not the identity of the removed vertex.
        # Convex combinations of strictly ordered sequences remain ordered.
        # At the same short-interval cutoff both activation and its derivative
        # vanish, so enabling/disabling this operation cannot produce a jump.
        # Other decisions (recipient interval, count, pattern fallback) still
        # need independent continuity qualification.
        short_length=(right-left)*length
        x=c.bounded(g,short_length/(.05*cell))
        activation=active*(1.-x*x*(3.-2.*x))
        old_t=c._read(g,table,'st_cq_t',index)
        new_t=c._read(g,redistributed,'st_cq_t',index)
        redistributed=c._store(g,redistributed,'st_cq_t',old_t+activation*(new_t-old_t))
    g.bind(redistributed,ro.inputs['Geometry'])
    g.bind(ro.outputs['Geometry'],out.inputs['Geometry']);g.bind(call.outputs['Valid'],out.inputs['Valid'])
    return g.g


def local_cluster_spacing(*,anchored=False):
    """Spread short-gap clusters without discrete cluster membership decisions.

    For a gap h and target T, pressure is
        p(h) = T/4 * (1-x) * (1-3*x*x+2*x*x*x), x=clamp(h/T,0,1).
    An interior station moves by p(left gap)-p(right gap); endpoints are fixed.
    Apply 32 simultaneous steps. Pressure and its derivative vanish at T, so
    no pair selection, visited mask or sorting transition can move columns.

    On nonnegative gaps p is decreasing and 27/64-Lipschitz. An interior gap
    therefore stays at least (1-2*27/64)*h = 5*h/32; a gap next to a fixed
    endpoint stays at least 37*h/64. Thus exact arithmetic preserves strict
    order even inside a cluster. Native boundary/shape checks remain mandatory
    for finite precision, curved sides, and the resulting interior quads.

    The anchored variant shifts only toward smaller t, by at most 45% of the
    preceding gap. The last point of each short-gap cluster therefore stays
    unchanged, retaining its adjoining curb segment. The explicit cap keeps
    every new gap at least 55% of the old gap. It is continuous, though the cap
    can introduce a derivative kink; it has no discrete cluster selection.
    """
    name='Prochitecture Streets / Local cluster quad stations v2'
    if anchored:name+=' / Anchored pressure v2'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    original=four.stations();g=c.Graph(name)
    for socket in original.interface.items_tree:
        if socket.item_type=='SOCKET':
            g.socket(socket.name,socket.socket_type,socket.in_out,default=getattr(socket,'default_value',None))
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput')
    call=g.node('GeometryNodeGroup');call.node_tree=original
    for socket in original.interface.items_tree:
        if socket.item_type=='SOCKET' and socket.in_out=='INPUT':g.bind(inp.outputs[socket.name],call.inputs[socket.name])
    length=c._read(g,inp.outputs['Plan'],'st_cq_length',inp.outputs['Index'])
    target=(.05 if anchored else .03)*g.math('MAXIMUM',c.V(g,inp.outputs['Cell Size']),.02)/g.math('MAXIMUM',length,1e-12)
    ri=g.node('GeometryNodeRepeatInput','Bounded continuous pressure on short-gap clusters')
    ro=g.node('GeometryNodeRepeatOutput');ri.pair_with_output(ro)
    g.bind(call.outputs['Geometry'],ri.inputs['Geometry'])
    g.bind(c.choose(g,call.outputs['Valid'],32,0,'INT'),ri.inputs['Iterations'])
    table=ri.outputs['Geometry'];count=c._count(g,table)
    index=c.V(g,g.node('GeometryNodeInputIndex').outputs[0]);t=c.named(g,'st_cq_t')
    previous=c._read(g,table,'st_cq_t',g.math('MAXIMUM',index-1.,0.))
    following=c._read(g,table,'st_cq_t',g.math('MINIMUM',index+1.,count-1.))
    def pressure(gap):
        x=c.bounded(g,gap/g.math('MAXIMUM',target,1e-12))
        return .25*target*(1.-x)*(1.-x*x*(3.-2.*x))
    interior=g.math('GREATER_THAN',index,.5)*g.math('LESS_THAN',index,count-1.5)
    if anchored:
        shift=g.math('MINIMUM',pressure(following-t),.45*g.math('MAXIMUM',t-previous,0.))
        shifted=t-shift
    else:
        shifted=t+pressure(t-previous)-pressure(following-t)
    updated=c._store(g,table,'st_cq_t',c.choose(g,interior,shifted,t))
    g.bind(updated,ro.inputs['Geometry'])
    g.bind(ro.outputs['Geometry'],out.inputs['Geometry']);g.bind(call.outputs['Valid'],out.inputs['Valid'])
    return g.g


def local_pair_spacing():
    """Expand close interior pairs locally without sorting or relocating columns.

    Move each member by at most 45% of its adjacent outer interval, keeping
    station order and fixed endpoints. Activation and its derivative vanish
    at the short-gap cutoff. Four disjoint pairs are considered; full boundary
    and final shape checks remain the caller's responsibility.
    """
    name='Prochitecture Streets / Local short-gap quad stations v1'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    original=four.stations();g=c.Graph(name)
    for socket in original.interface.items_tree:
        if socket.item_type=='SOCKET':
            g.socket(socket.name,socket.socket_type,socket.in_out,default=getattr(socket,'default_value',None))
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput')
    call=g.node('GeometryNodeGroup');call.node_tree=original
    for socket in original.interface.items_tree:
        if socket.item_type=='SOCKET' and socket.in_out=='INPUT':g.bind(inp.outputs[socket.name],call.inputs[socket.name])
    length=c._read(g,inp.outputs['Plan'],'st_cq_length',inp.outputs['Index'])
    target=.03*g.math('MAXIMUM',c.V(g,inp.outputs['Cell Size']),.02)/g.math('MAXIMUM',length,1e-12)
    ri=g.node('GeometryNodeRepeatInput','Expand at most four disjoint close pairs')
    ro=g.node('GeometryNodeRepeatOutput');ri.pair_with_output(ro)
    g.bind(c._store(g,call.outputs['Geometry'],'_sr_visited',False,'BOOLEAN'),ri.inputs['Geometry'])
    g.bind(c.choose(g,call.outputs['Valid'],4,0,'INT'),ri.inputs['Iterations'])
    table=ri.outputs['Geometry'];count=c._count(g,table)
    index=c.V(g,g.node('GeometryNodeInputIndex').outputs[0]);t=c.named(g,'st_cq_t')
    read=lambda key,at,kind='FLOAT':c._read(g,table,key,c.bounded(g,at,0.,count-1.),kind)
    previous=read('st_cq_t',index-1.)
    available=(1.-c.named(g,'_sr_visited','BOOLEAN'))*(1.-read('_sr_visited',index-1.,'BOOLEAN'))
    short=available*g.math('GREATER_THAN',index,1.5)*g.math('LESS_THAN',index,count-1.5)*g.math('LESS_THAN',t-previous,target)
    pair=c._stat(g,table,c.choose(g,short,index,four.MAX_ROWS),'Min')
    active=g.math('LESS_THAN',pair,count)
    a=read('st_cq_t',pair-1.);b=read('st_cq_t',pair)
    x=c.bounded(g,(b-a)/g.math('MAXIMUM',target,1e-12))
    requested=.5*g.math('MAXIMUM',target-(b-a),0.)*(1.-x*x*(3.-2.*x))
    room=.45*g.math('MINIMUM',a-read('st_cq_t',pair-2.),read('st_cq_t',pair+1.)-b)
    shift=active*g.math('MINIMUM',requested,g.math('MAXIMUM',room,0.))
    left=g.math('COMPARE',index,pair-1.);right=g.math('COMPARE',index,pair)
    updated=c._store(g,table,'st_cq_t',t+shift*(right-left))
    updated=c._store(g,updated,'_sr_visited',g.math('MAXIMUM',c.named(g,'_sr_visited','BOOLEAN'),active*g.math('MAXIMUM',left,right)),'BOOLEAN')
    g.bind(updated,ro.inputs['Geometry'])
    g.bind(ro.outputs['Geometry'],out.inputs['Geometry']);g.bind(call.outputs['Valid'],out.inputs['Valid'])
    return g.g
